         <button onClick={() => setView(ViewState.DASHBOARD)} className="text-sm text-indigo-600 font-medium">Menu</button>
      </div>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pt-16 md:pt-0">
        <div className="max-w-5xl mx-auto p-4 md:p-8">
          {children}
        </div>
      </main>

      {/* Mobile Bottom Nav */}
      <div className="md:hidden fixed bottom-0 w-full bg-white border-t border-slate-200 flex justify-around p-3 z-10">
          {navItems.map((item) => {
             const Icon = item.icon;
             const isActive = currentView === item.view;
             return (
               <button 
                 key={item.view}
                 onClick={() => setView(item.view)}
                 className={`flex flex-col items-center gap-1 ${isActive ? 'text-indigo-600' : 'text-slate-400'}`}
               >
                 <Icon className="w-5 h-5" />
                 <span className="text-[10px]">{item.label}</span>
               </button>
             )
          })}
      </div>
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import { StudentProfile } from '../types';
import { BookOpen, Check, Target, Brain, Clock, Calendar, Plus, Trash2 } from 'lucide-react';

interface ProfileSetupProps {
  initialName: string;
  onComplete: (profile: StudentProfile) => void;
}

const ProfileSetup: React.FC<ProfileSetupProps> = ({ initialName, onComplete }) => {
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<StudentProfile>({
    name: initialName,
    gradeLevel: '',
    subjects: [],
    strengths: [],
    weaknesses: [],
    dailyStudyHours: 2,
    upcomingExams: ''
  });

  const [subjectInput, setSubjectInput] = useState('');

  // State for exam list builder
  const [examName, setExamName] = useState('');
  const [examDate, setExamDate] = useState('');
  const [examList, setExamList] = useState<{name: string, date: string}[]>([]);

  const handleNext = () => setStep(s => s + 1);
  const handleBack = () => setStep(s => s - 1);

  const addSubject = (list: 'subjects' | 'strengths' | 'weaknesses', value: string) => {
    if (value.trim() && !profile[list].includes(value)) {
      setProfile(prev => ({ ...prev, [list]: [...prev[list], value] }));
    }
  };

  const removeSubject = (list: 'subjects' | 'strengths' | 'weaknesses', value: string) => {
    setProfile(prev => ({ ...prev, [list]: prev[list].filter(s => s !== value) }));
  };

  const addExam = () => {
    if (examName && examDate) {
      const newList = [...examList, { name: examName, date: examDate }];
      setExamList(newList);
      setExamName('');
      setExamDate('');
      // Update profile string representation
      const examString = newList.map(e => `${e.name} on ${e.date}`).join(', ');
      setProfile(prev => ({ ...prev, upcomingExams: examString }));
    }
  };

  const removeExam = (idx: number) => {
    const newList = examList.filter((_, i) => i !== idx);
    setExamList(newList);
    const examString = newList.map(e => `${e.name} on ${e.date}`).join(', ');
    setProfile(prev => ({ ...prev, upcomingExams: examString }));
  };

  const renderStep = () => {
    switch(step) {
      case 1:
        return (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
              <BookOpen className="text-indigo-500" />
              Academic Basics
            </h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Current Grade/Level</label>
                <select 
                  className="w-full p-3 bg-white border border-slate-200 text-slate-900 rounded-xl outline-none focus:ring-2 focus:ring-indigo-200"
                  value={profile.gradeLevel}
                  onChange={e => setProfile({...profile, gradeLevel: e.target.value})}
                >
                  <option value="">Select Level</option>
                  <option value="High School - Freshman">High School - Freshman</option>
                  <option value="High School - Sophomore">High School - Sophomore</option>
                  <option value="High School - Junior">High School - Junior</option>
                  <option value="High School - Senior">High School - Senior</option>
                  <option value="College - Undergraduate">College - Undergraduate</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">What subjects are you studying?</label>
                <div className="flex gap-2 mb-2">
                  <input 
                    type="text" 
                    value={subjectInput}
                    onChange={e => setSubjectInput(e.target.value)}
                    onKeyDown={e => {
                        if(e.key === 'Enter') {
                            addSubject('subjects', subjectInput);
                            setSubjectInput('');
                        }
                    }}
                    placeholder="e.g. Math, Biology, History"
                    className="flex-1 p-3 bg-white border border-slate-200 text-slate-900 rounded-xl outline-none focus:ring-2 focus:ring-indigo-200"
                  />
                  <button 
                    onClick={() => {
                        addSubject('subjects', subjectInput);
                        setSubjectInput('');
                    }}
                    className="bg-slate-800 text-white px-4 rounded-xl hover:bg-slate-900"
                  >
                    Add
                  </button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {profile.subjects.map(s => (
                    <span key={s} className="bg-slate-100 text-slate-700 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                      {s}
                      <button onClick={() => removeSubject('subjects', s)} className="text-slate-400 hover:text-red-500">×</button>
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
              <Brain className="text-indigo-500" />
              Strengths & Weaknesses
            </h2>
            <p className="text-slate-500 text-sm">Select from your subjects above.</p>

            <div className="grid md:grid-cols-2 gap-6">
              <div className="bg-green-50 p-4 rounded-xl border border-green-100">
                <h3 className="font-semibold text-green-800 mb-3 flex items-center gap-2">
                  <Target className="w-4 h-4" /> Strongest Subjects
                </h3>
                <div className="flex flex-wrap gap-2">
                  {profile.subjects.map(s => (
                    <button
                      key={s}
                      onClick={() => {
                        if (profile.strengths.includes(s)) removeSubject('strengths', s);
                        else addSubject('strengths', s);
                      }}
                      className={`px-3 py-1 rounded-full text-sm border transition-colors ${
                        profile.strengths.includes(s) 
                          ? 'bg-green-500 text-white border-green-600' 
                          : 'bg-white text-slate-600 border-slate-200 hover:border-green-300'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div className="bg-orange-50 p-4 rounded-xl border border-orange-100">
                <h3 className="font-semibold text-orange-800 mb-3 flex items-center gap-2">
                   Needs Improvement
                </h3>
                <div className="flex flex-wrap gap-2">
                  {profile.subjects.map(s => (
                    <button
                      key={s}
                      onClick={() => {
                        if (profile.weaknesses.includes(s)) removeSubject('weaknesses', s);
                        else addSubject('weaknesses', s);
                      }}
                      className={`px-3 py-1 rounded-full text-sm border transition-colors ${
                        profile.weaknesses.includes(s) 
                          ? 'bg-orange-500 text-white border-orange-600' 
                          : 'bg-white text-slate-600 border-slate-200 hover:border-orange-300'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      case 3:
        return (
            <div className="space-y-6">
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
              <Clock className="text-indigo-500" />
              Goals & Exams
            </h2>

            <div className="space-y-6">
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Daily Study Goal (Hours)</label>
                    <input 
                        type="range" 
                        min="0.5" 
                        max="8" 
                        step="0.5"
                        value={profile.dailyStudyHours}
                        onChange={e => setProfile({...profile, dailyStudyHours: parseFloat(e.target.value)})}
                        className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer"
                    />
                    <div className="mt-2 text-center font-bold text-indigo-600 text-xl">
                        {profile.dailyStudyHours} Hours / Day
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Upcoming Exams or Deadlines</label>

                    {/* Add Exam Form */}
                    <div className="flex flex-col md:flex-row gap-2 mb-4">
                        <input
                            type="text"
                            placeholder="Exam Name (e.g. Math Midterm)"
                            value={examName}
                            onChange={(e) => setExamName(e.target.value)}
                            className="flex-1 p-3 bg-white border border-slate-200 text-slate-900 rounded-xl outline-none focus:ring-2 focus:ring-indigo-200"
                        />
                        <div className="flex gap-2">
                            <input
                                type="date"
                                value={examDate}
                                onChange={(e) => setExamDate(e.target.value)}
                                className="p-3 bg-white border border-slate-200 text-slate-900 rounded-xl outline-none focus:ring-2 focus:ring-indigo-200"
                            />
                            <button 
                                onClick={addExam}
                                disabled={!examName || !examDate}
                                className="bg-indigo-600 text-white px-4 rounded-xl hover:bg-indigo-700 disabled:opacity-50 flex items-center justify-center"
                            >
                                <Plus className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {/* Exam List */}
                    <div className="space-y-2">
                        {examList.length === 0 && (
                            <div className="text-slate-400 text-center py-4 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                                <Calendar className="w-6 h-6 mx-auto mb-1 opacity-50" />
                                No exams added yet.
                            </div>
                        )}
                        {examList.map((exam, idx) => (
                            <div key={idx} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-xl">
                                <div className="flex items-center gap-3">
                                    <div className="bg-indigo-50 text-indigo-600 p-2 rounded-lg">
                                        <Calendar className="w-4 h-4" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-slate-800">{exam.name}</p>
                                        <p className="text-xs text-slate-500">{exam.date}</p>
                                    </div>
                                </div>
                                <button onClick={() => removeExam(idx)} className="text-slate-400 hover:text-red-500">
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
          </div>
        )
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center">
            <div>
                <h1 className="text-2xl font-bold">Set Up Profile</h1>
                <p className="text-indigo-100 text-sm">Help us personalize your experience, {initialName}.</p>
            </div>
            <div className="text-3xl font-bold opacity-20">0{step}</div>
        </div>

        <div className="p-8">
            {renderStep()}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-between">
            {step > 1 ? (
                <button 
                    onClick={handleBack}
                    className="px-6 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition-colors"
                >
                    Back
                </button>
            ) : <div></div>}

            {step < 3 ? (
                 <button 
                    onClick={handleNext}
                    disabled={step === 1 && profile.subjects.length === 0}
                    className={`px-6 py-2 bg-indigo-600 text-white rounded-lg font-medium transition-colors ${
                        step === 1 && profile.subjects.length === 0 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-indigo-700'
                    }`}
                >
                    Next
                </button>
            ) : (
                <button 
                    onClick={() => onComplete(profile)}
                    className="px-6 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium flex items-center gap-2 transition-colors"
                >
                    <Check className="w-4 h-4" /> Finish Setup
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

export default ProfileSetup;

import React, { useState } from 'react';
import { StudentProfile, DailyPlan } from '../types';
import { generateStudyPlan, updateStudyPlan } from '../services/geminiService';
import { Sparkles, Clock, Book, RotateCcw, Send, Edit3, Loader2 } from 'lucide-react';

interface PlannerProps {
  profile: StudentProfile;
}

const Planner: React.FC<PlannerProps> = ({ profile }) => {
  const [plan, setPlan] = useState<DailyPlan | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Customization state
  const [adjustPrompt, setAdjustPrompt] = useState('');
  const [isAdjusting, setIsAdjusting] = useState(false);

  const handleGeneratePlan = async () => {
    setLoading(true);
    setError('');
    try {
      const newPlan = await generateStudyPlan(profile);
      setPlan(newPlan);
    } catch (err) {
      setError('Failed to generate plan. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleAdjustPlan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adjustPrompt.trim() || !plan) return;

    setIsAdjusting(true);
    try {
        const updatedPlan = await updateStudyPlan(plan, adjustPrompt, profile);
        setPlan(updatedPlan);
        setAdjustPrompt('');
    } catch (err) {
        setError('Could not update the plan. Try again.');
    } finally {
        setIsAdjusting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] text-center space-y-4">
        <div className="relative">
            <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <Sparkles className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-indigo-600 w-6 h-6" />
        </div>
        <div>
            <h2 className="text-xl font-bold text-slate-800">Designing your day...</h2>
            <p className="text-slate-500">Analyzing your subjects and goals.</p>
        </div>
      </div>
    );
  }

  if (!plan) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] text-center max-w-lg mx-auto">
        <div className="bg-indigo-50 p-6 rounded-full mb-6">
            <Clock className="w-12 h-12 text-indigo-600" />
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-3">No Plan for Today Yet</h2>
        <p className="text-slate-500 mb-8">
            Let our AI create a personalized schedule that balances your strengths, weaknesses, and breaks.
        </p>
        <button
          onClick={handleGeneratePlan}
          className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-3 px-8 rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center gap-2"
        >
          <Sparkles className="w-5 h-5" />
          Generate Today's Plan
        </button>
        {error && <p className="text-red-500 mt-4">{error}</p>}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20 md:pb-0">
      <div className="bg-gradient-to-r from-indigo-600 to-purple-600 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex justify-between items-start">
            <div>
                <h2 className="text-2xl font-bold mb-2">Today's Blueprint</h2>
                <p className="text-indigo-100 opacity-90">{plan.date}</p>
            </div>
            <button 
                onClick={handleGeneratePlan}
                className="bg-white/20 hover:bg-white/30 text-white p-2 rounded-lg transition-colors"
                title="Regenerate Plan"
            >
                <RotateCcw className="w-5 h-5" />
            </button>
        </div>
        <div className="mt-6 bg-white/10 backdrop-blur-sm p-4 rounded-xl border border-white/20">
            <p className="font-medium italic">"{plan.motivationalQuote}"</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Timeline */}
        <div className="lg:col-span-2 relative">
             <div className="absolute left-8 top-0 bottom-0 w-0.5 bg-slate-200 hidden md:block"></div>
             <div className="space-y-6">
                {plan.sessions.map((session, index) => (
                    <div key={index} className="relative flex flex-col md:flex-row gap-6 group">
                        {/* Time Bubble */}
                        <div className="md:w-32 flex-shrink-0 flex md:justify-end">
                            <div className="bg-white border border-slate-200 text-slate-600 font-semibold py-1 px-3 rounded-lg text-sm shadow-sm h-fit z-10">
                                {session.time}
                            </div>
                        </div>

                        {/* Card */}
                        <div className="flex-1 bg-white p-5 rounded-2xl border border-slate-200 shadow-sm group-hover:shadow-md transition-shadow relative">
                            <div className="absolute top-5 -left-2 w-4 h-4 bg-white border-2 border-slate-200 rotate-45 hidden md:block"></div>
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                                    <Book className="w-4 h-4 text-indigo-500" />
                                    {session.subject}
                                </h3>
                                <span className="text-xs font-medium text-slate-500 bg-slate-100 px-2 py-1 rounded-full">
                                    {session.duration}
                                </span>
                            </div>
                            <p className="text-slate-600 mb-4">{session.activity}</p>

                            <div className="bg-indigo-50 text-indigo-700 text-sm p-3 rounded-lg flex items-start gap-2">
                                <Sparkles className="w-4 h-4 mt-0.5 flex-shrink-0" />
                                {session.tip}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>

        {/* AI Customization Sidebar */}
        <div className="lg:col-span-1">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 sticky top-6">
                <div className="flex items-center gap-2 mb-4 text-slate-800">
                    <Edit3 className="w-5 h-5 text-indigo-600" />
                    <h3 className="font-bold">Adjust Plan</h3>
                </div>
                <p className="text-sm text-slate-500 mb-4">
                    Something came up? Tell the AI to tweak your schedule.
                </p>
                <form onSubmit={handleAdjustPlan}>
                    <textarea
                        value={adjustPrompt}
                        onChange={(e) => setAdjustPrompt(e.target.value)}
                        placeholder="e.g., I have a dentist appointment at 4pm, or I'm too tired for Math..."
                        className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl mb-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 resize-none h-32"
                    />
                    <button
                        type="submit"
                        disabled={!adjustPrompt.trim() || isAdjusting}
                        className="w-full bg-slate-900 text-white py-2 rounded-xl text-sm font-medium hover:bg-slate-800 disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {isAdjusting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                        Update Schedule
                    </button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Planner;

import React, { useState, useEffect, useRef } from 'react';
import { ShieldBan, Clock, Bell, Volume2, Lock, Unlock, Play, Pause, RotateCcw } from 'lucide-react';

const FocusTools: React.FC = () => {
  const [apps, setApps] = useState([
    { name: 'Instagram', icon: '📸', blocked: false },
    { name: 'TikTok', icon: '🎵', blocked: false },
    { name: 'Snapchat', icon: '👻', blocked: false },
    { name: 'Video Games', icon: '🎮', blocked: false },
    { name: 'Messages', icon: '💬', blocked: false },
  ]);

  const [timeLeft, setTimeLeft] = useState(25 * 60); // 25 minutes default
  const [isActive, setIsActive] = useState(false);
  const [isBreak, setIsBreak] = useState(false);
  const [alarmPlaying, setAlarmPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    let interval: number | null = null;

    if (isActive && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((time) => time - 1);
      }, 1000);
    } else if (timeLeft === 0 && isActive) {
      setIsActive(false);
      playAlarm();
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const toggleBlock = (index: number) => {
    const newApps = [...apps];
    newApps[index].blocked = !newApps[index].blocked;
    setApps(newApps);
  };

  const blockAll = () => {
    setApps(apps.map(app => ({ ...app, blocked: true })));
  };

  const playAlarm = () => {
    setAlarmPlaying(true);
    // Simple beep sound using Web Audio API if no file provided, 
    // but here we simulate with a visual indicator and a delayed stop
    // In a real app, use new Audio('/alarm.mp3').play()
    setTimeout(() => setAlarmPlaying(false), 5000); 
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(isBreak ? 5 * 60 : 25 * 60);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex items-center gap-3 mb-2">
        <ShieldBan className="w-8 h-8 text-indigo-600" />
        <h1 className="text-3xl font-bold text-slate-800">Focus Zone</h1>
      </div>
      <p className="text-slate-500">Minimize distractions and manage your time effectively.</p>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* Timer Section */}
        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm flex flex-col items-center justify-center relative overflow-hidden">
          {alarmPlaying && (
            <div className="absolute inset-0 bg-red-500/10 z-0 animate-pulse flex items-center justify-center">
                <Bell className="w-32 h-32 text-red-500 opacity-20 alarm-ring" />
            </div>
          )}

          <div className="relative z-10 text-center">
             <div className="flex items-center justify-center gap-2 mb-6">
                <button 
                    onClick={() => { setIsBreak(false); setTimeLeft(25*60); setIsActive(false); }}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${!isBreak ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
                >
                    Focus Mode
                </button>
                <button 
                    onClick={() => { setIsBreak(true); setTimeLeft(5*60); setIsActive(false); }}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${isBreak ? 'bg-emerald-100 text-emerald-700' : 'text-slate-500 hover:bg-slate-100'}`}
                >
                    Break Mode
                </button>
             </div>

             <div className="text-7xl font-bold text-slate-800 font-mono mb-8 tracking-wider">
                {formatTime(timeLeft)}
             </div>

             <div className="flex gap-4">
                <button 
                    onClick={() => setIsActive(!isActive)}
                    className="w-16 h-16 rounded-full bg-indigo-600 text-white flex items-center justify-center hover:bg-indigo-700 shadow-lg hover:scale-105 transition-all"
                >
                    {isActive ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 ml-1 fill-current" />}
                </button>
                <button 
                    onClick={resetTimer}
                    className="w-16 h-16 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center hover:bg-slate-200 transition-colors"
                >
                    <RotateCcw className="w-6 h-6" />
                </button>
             </div>
          </div>
        </div>

        {/* App Blocker Section */}
        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
           <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                 <Lock className="w-5 h-5 text-red-500" />
                 App Blocker
              </h2>
              <button 
                onClick={blockAll}
                className="text-xs font-semibold text-indigo-600 hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-colors"
              >
                Block All
              </button>
           </div>

           <div className="space-y-3">
              {apps.map((app, idx) => (
                  <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                      <div className="flex items-center gap-3">
                          <span className="text-2xl">{app.icon}</span>
                          <span className="font-medium text-slate-700">{app.name}</span>
                      </div>
                      <button 
                        onClick={() => toggleBlock(idx)}
                        className={`relative w-12 h-6 rounded-full transition-colors duration-200 ease-in-out ${app.blocked ? 'bg-red-500' : 'bg-slate-300'}`}
                      >
                         <span className={`absolute top-1 left-1 bg-white w-4 h-4 rounded-full shadow transition-transform duration-200 ease-in-out ${app.blocked ? 'translate-x-6' : 'translate-x-0'}`} />
                      </button>
                  </div>
              ))}
           </div>

           <div className="mt-6 p-4 bg-yellow-50 rounded-xl border border-yellow-100 text-sm text-yellow-800 flex gap-3">
              <ShieldBan className="w-5 h-5 flex-shrink-0" />
              <p>
                  Note: Apps selected here will be visually flagged. Enable "Do Not Disturb" on your device for system-wide blocking.
              </p>
           </div>
        </div>
      </div>
    </div>
  );
};

export default FocusTools;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Login from './components/Login';
import ProfileSetup from './components/ProfileSetup';
import Dashboard from './components/Dashboard';
import Planner from './components/Planner';
import AIChat from './components/AIChat';
import Progress from './components/Progress';
import FocusTools from './components/FocusTools';
import { ViewState, StudentProfile } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LOGIN);
  const [userName, setUserName] = useState('');
  const [profile, setProfile] = useState<StudentProfile | null>(null);

  // Mock streak data
  const [streak] = useState(5);

  const handleLogin = (name: string) => {
    setUserName(name);
    // In a real app, we would check if profile exists for this user
    setView(ViewState.PROFILE_SETUP);
  };

  const handleProfileComplete = (newProfile: StudentProfile) => {
    setProfile(newProfile);
    setView(ViewState.DASHBOARD);
  };

  const renderContent = () => {
    switch (view) {
      case ViewState.LOGIN:
        return <Login onLogin={handleLogin} />;

      case ViewState.PROFILE_SETUP:
        return <ProfileSetup initialName={userName} onComplete={handleProfileComplete} />;

      case ViewState.DASHBOARD:
        if (!profile) return null;
        return <Dashboard profile={profile} setView={setView} streak={streak} />;

      case ViewState.PLANNER:
        if (!profile) return null;
        return <Planner profile={profile} />;

      case ViewState.CHAT:
        if (!profile) return null;
        return <AIChat profile={profile} />;

      case ViewState.PROGRESS:
        if (!profile) return null;
        return <Progress profile={profile} />;

      case ViewState.FOCUS_TOOLS:
        return <FocusTools />;

      default:
        return <div>View not found</div>;
    }
  };

  // If we are in Login or Profile Setup, we don't show the main dashboard layout
  if (view === ViewState.LOGIN || view === ViewState.PROFILE_SETUP) {
    return renderContent();
  }

  // Main Layout for authenticated views
  return (
    <Layout currentView={view} setView={setView} userName={userName}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { StudentProfile, DailyPlan } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_FLASH = "gemini-3-flash-preview";

export const generateStudyPlan = async (profile: StudentProfile): Promise<DailyPlan> => {
  const prompt = `
    Create a supportive and balanced daily study plan for a student with the following profile:
    Name: ${profile.name}
    Grade: ${profile.gradeLevel}
    Subjects: ${profile.subjects.join(", ")}
    Strengths: ${profile.strengths.join(", ")}
    Weaknesses: ${profile.weaknesses.join(", ")} (Please allocate slightly more time or easier entry tasks for these)
    Daily Goal: ${profile.dailyStudyHours} hours
    Upcoming Exams: ${profile.upcomingExams}

    The plan should be realistic, include breaks, and use a motivating tone.
    Provide the response in JSON format strictly adhering to the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_FLASH,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            date: { type: Type.STRING, description: "Today's date formatted appropriately" },
            motivationalQuote: { type: Type.STRING, description: "A short, encouraging quote for the student" },
            sessions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  time: { type: Type.STRING, description: "e.g., 4:00 PM - 4:45 PM" },
                  subject: { type: Type.STRING },
                  activity: { type: Type.STRING, description: "Specific study task (e.g., Read Chapter 4, Solve 5 problems)" },
                  duration: { type: Type.STRING, description: "Duration in minutes" },
                  tip: { type: Type.STRING, description: "A quick study tip or encouragement specific to this task" },
                },
                required: ["time", "subject", "activity", "duration", "tip"]
              }
            }
          },
          required: ["date", "sessions", "motivationalQuote"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from Gemini");
    return JSON.parse(text) as DailyPlan;

  } catch (error) {
    console.error("Error generating study plan:", error);
    throw error;
  }
};

export const updateStudyPlan = async (currentPlan: DailyPlan, feedback: string, profile: StudentProfile): Promise<DailyPlan> => {
  const prompt = `
    The student wants to adjust their current study plan.

    Current Plan: ${JSON.stringify(currentPlan)}
    Student Feedback/Constraints: "${feedback}"
    Student Profile: ${JSON.stringify(profile)}

    Please modify the sessions to accommodate the feedback while maintaining the daily study goal if possible (or adjusting it realistically). 
    If the student says they are busy or tired, reduce the load.
    If the student adds a specific event (like "Doctor at 3pm"), work around it.

    Keep the same date and motivational quote unless the feedback implies changing them.
    Provide the response in JSON format strictly adhering to the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_FLASH,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            date: { type: Type.STRING },
            motivationalQuote: { type: Type.STRING },
            sessions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  time: { type: Type.STRING },
                  subject: { type: Type.STRING },
                  activity: { type: Type.STRING },
                  duration: { type: Type.STRING },
                  tip: { type: Type.STRING },
                },
                required: ["time", "subject", "activity", "duration", "tip"]
              }
            }
          },
          required: ["date", "sessions", "motivationalQuote"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from Gemini");
    return JSON.parse(text) as DailyPlan;

  } catch (error) {
    console.error("Error updating study plan:", error);
    throw error;
  }
};

export const getTutorResponseStream = async (
  history: { role: string; parts: { text: string }[] }[],
  message: string,
  profile: StudentProfile
) => {
  try {
    const systemInstruction = `
      You are a supportive, patient, and encouraging AI Study Buddy for a student named ${profile.name}.
      Your goal is to explain academic concepts simply, help with planning, and boost confidence.

      Guidelines:
      1. Tone: Warm, mentor-like, never judgmental. Use emojis occasionally.
      2. If the student is stressed, validate their feelings and suggest a small, manageable step.
      3. Explain concepts step-by-step using analogies suitable for grade level ${profile.gradeLevel}.
      4. If asked about weak subjects (${profile.weaknesses.join(", ")}), be extra encouraging.
      5. Keep responses concise unless a deep explanation is requested.
    `;

    const chat = ai.chats.create({
      model: MODEL_FLASH,
      config: {
        systemInstruction: systemInstruction,
      },
      history: history.map(h => ({
        role: h.role,
        parts: h.parts
      }))
    });

    return await chat.sendMessageStream({ message });
  } catch (error) {
    console.error("Error in chat stream:", error);
    throw error;
  }
};

export const analyzeProgress = async (profile: StudentProfile, progressData: any) => {
    // This is a helper to get a text summary of progress
    const prompt = `
        Analyze the following study progress for ${profile.name}:
        ${JSON.stringify(progressData)}

        Give 3 short, bulleted positive reinforcements and 1 gentle suggestion for improvement.
        Keep it under 100 words total.
    `;

    const response = await ai.models.generateContent({
        model: MODEL_FLASH,
        contents: prompt
    });

    return response.text || "Keep up the great work! Consistency is key.";
}
